CREATE TABLE economic_evidence_vault (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES economic_onboarding_profiles(id) ON DELETE CASCADE, activity_id uuid REFERENCES economic_activity_records(id) ON DELETE SET NULL, evidence_category text NOT NULL, title text NOT NULL, description text, source_type text NOT NULL DEFAULT 'self_reported', verification_status text NOT NULL DEFAULT 'submitted', storage_url text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, submitted_by text NOT NULL, reviewed_by text, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());